package fr.gemsofrod.encyclopedie.data

/** English translations of the name, descriptive texts and jewellery interest of seashells. */
object CoquillageTranslationsEn {
    val data: Map<String, CoquillageTranslation> = mapOf(
        "coquillage-ormeau" to CoquillageTranslation(
            nom = "Abalone",
            descriptionCourte = "The shell of a large marine gastropod, lined with a shimmering mother-of-pearl highly prized in jewellery.",
            descriptionLongue = "Abalone is a herbivorous gastropod mollusc that lives fixed to rocks in cold, algae-rich waters. Its flattened, ear-shaped shell, pierced with a row of breathing holes, hides a nacre of exceptional iridescence ranging from blue-green to violet depending on the angle of light — a play of colour caused by the microscopic layered structure of aragonite that diffracts light rather than by any pigment. Widely used in marquetry and costume jewellery.",
            interetJoaillerie = "Excellent: inlays, buttons, pendants and jewellery in whole mother-of-pearl"
        ),
        "coquillage-cauri-monnaie" to CoquillageTranslation(
            nom = "Money Cowrie",
            descriptionCourte = "A small, smooth, glossy shell that served as a medium of exchange on three continents for centuries.",
            descriptionLongue = "From the East African coast to Southeast Asia and on into Oceania, this small gastropod with its lustrous, dome-backed shell long circulated as currency, to the point of lending its name to local monetary units. Its naturally hard, polished, porcelain-like surface made it an ornament strung into necklaces and traditional jewellery long before the appearance of metal coins.",
            interetJoaillerie = "Moderate: strung beads, ethnic jewellery, décor"
        ),
        "coquillage-cypree-doree" to CoquillageTranslation(
            nom = "Golden Cowrie",
            descriptionCourte = "A vivid orange shell long reserved for Pacific chiefs, a symbol of power and social rank.",
            descriptionLongue = "In the traditional societies of Melanesia and Polynesia, the golden cowrie was an ornament reserved for chiefs and high-ranking figures, worn as a pendant on the chest as an insignia of power — a social use comparable to that of precious stones in other cultures. Its intense orange colour and exceptional natural gloss make it today one of the most sought-after cowries among shell collectors worldwide.",
            interetJoaillerie = "Historic: chief's ornament, ceremonial pendant mounted whole and unworked"
        ),
        "coquillage-conque-reine" to CoquillageTranslation(
            nom = "Queen Conch",
            descriptionCourte = "A large Caribbean gastropod with a vivid pink interior, the historic raw material of carved cameos.",
            descriptionLongue = "This large conical shell, traditionally fished in the Caribbean for its meat, owes its gemmological fame to its thick, graduated pink-to-cream layer, carved into cameos by the Italian workshops of Torre del Greco since the 19th century. It also very rarely produces pink, flame-structured, non-nacreous \"conch pearls\", among the most expensive organic gems in the world — structurally unrelated to the classic nacreous pearl.",
            interetJoaillerie = "Good: Torre del Greco cameos, exceedingly rare non-nacreous conch pearls"
        ),
        "coquillage-trocas" to CoquillageTranslation(
            nom = "Trochus",
            descriptionCourte = "An Indo-Pacific conical shell with thick white nacre, the main raw material of mother-of-pearl button-making.",
            descriptionLongue = "Before the advent of plastic, this large conical gastropod supplied most of the white mother-of-pearl used in Western button-making and marquetry, its thick, regular shell lending itself particularly well to cutting. The species is now farmed under regulated aquaculture on several Pacific islands, ensuring more sustainable exploitation than in the 19th century.",
            interetJoaillerie = "Excellent: historic raw material of mother-of-pearl button-making"
        ),
        "coquillage-burgau-vert" to CoquillageTranslation(
            nom = "Green Turban Shell",
            descriptionCourte = "One of the largest nacreous gastropods of the Pacific, its emerald-green shell highly sought after in luxury marquetry.",
            descriptionLongue = "This giant turban shell, among the largest nacreous gastropods in existence, produces a thick nacre in emerald-green to silvery tones particularly prized by cabinetmakers and Japanese lacquer workshops for the marquetry technique known as raden. Its shell, rarer on the market than that of the trochus, reaches impressive sizes exceeding 20 centimetres in diameter.",
            interetJoaillerie = "Very good: luxury marquetry, inlays on lacquer and fine wood"
        ),
        "coquillage-murex-pourpre" to CoquillageTranslation(
            nom = "Purple Dye Murex",
            descriptionCourte = "A spiny Mediterranean gastropod whose hypobranchial gland supplied Tyrian purple, the most prestigious textile dye of antiquity.",
            descriptionLongue = "This spine-covered gastropod is of interest to jewellery not for its nacre — it produces almost none — but for its major historical role: its hypobranchial gland secretes a mucus that, exposed to air and light, turns deep purple. Tens of thousands of broken shells found near the ancient Phoenician workshops of Tyre and Sidon bear witness to the production of this textile dye reserved for royal and imperial garments in antiquity.",
            interetJoaillerie = "Historic: the source of Tyrian purple, the most prestigious textile dye of antiquity"
        ),
        "coquillage-lambis" to CoquillageTranslation(
            nom = "Spider Conch",
            descriptionCourte = "An Indo-Pacific shell recognisable by its long, pointed finger-like projections evoking a spider's legs.",
            descriptionLongue = "A more modest cousin of the Caribbean queen conch, this Indo-Pacific lagoon-dwelling strombid develops a series of slender projections along its outer lip, earning it its \"spider\" nickname. Its shell, very common on coastal craft markets, is mostly appreciated whole as a decorative object rather than as a raw material to be cut.",
            interetJoaillerie = "Moderate: décor, occasional elements in ethnic jewellery"
        ),
        "coquillage-huitre-perliere-noire" to CoquillageTranslation(
            nom = "Black-lipped Pearl Oyster",
            descriptionCourte = "The bivalve that produces the famous Tahitian pearls, its inner nacre anthracite grey with coloured shimmers.",
            descriptionLongue = "This large oyster from the Polynesian lagoons is world-famous for producing, through pearl farming, Tahitian pearls in shades from grey-green to aubergine. Once the pearl is harvested, its shell itself yields an iridescent black nacre highly sought after in jewellery and marquetry, distinguished by its dark colour from the classic white nacre of other pearl oysters.",
            interetJoaillerie = "Excellent: shell that hosts Tahitian pearls, black nacre prized in jewellery"
        ),
        "coquillage-huitre-perliere-doree" to CoquillageTranslation(
            nom = "Gold-lipped Pearl Oyster",
            descriptionCourte = "The largest pearl oyster in the world, the source of the white and golden South Sea pearls.",
            descriptionLongue = "Able to reach 30 centimetres in diameter, this oyster is the largest of the commercially exploited nacreous species. Farmed in Australia and Southeast Asia, it produces South Sea pearls, white or golden depending on the strain, and yields after harvesting a thick nacre just as prized in jewellery as that of its black-lipped Tahitian cousin.",
            interetJoaillerie = "Excellent: shell that hosts South Sea pearls, prized golden nacre"
        ),
        "coquillage-saint-jacques" to CoquillageTranslation(
            nom = "Great Scallop",
            descriptionCourte = "The fan-shaped shell that became the emblem of the pilgrimage to Santiago de Compostela.",
            descriptionLongue = "Unlike most seashells featured in this section, the great scallop is not nacreous inside: its convex valve, marked with prominent radiating ribs, is composed of opaque prismatic calcite. Its interest lies chiefly in its shape, which over the centuries became the symbol of the pilgrimage to Santiago de Compostela and a recurring decorative and heraldic motif in religious jewellery.",
            interetJoaillerie = "Low: decorative object, symbol used in religious jewellery"
        ),
        "coquillage-spondyle" to CoquillageTranslation(
            nom = "Spiny Oyster",
            descriptionCourte = "A vividly coloured spiny bivalve, used as ritual exchange currency by the pre-Columbian civilisations of the Andes.",
            descriptionLongue = "Nicknamed \"the red gold of the Andes\", the spiny oyster was, for the pre-Columbian civilisations of Ecuador and Peru, an exchange good and a ritual object as precious as gold, associated with fertility and water. Its spine-covered shell, in spectacular shades of orange-red to violet, is today sawn and polished into coloured beads and cabochons for ethnic and contemporary jewellery.",
            interetJoaillerie = "Historic and current: pre-Columbian exchange currency, coloured beads and jewellery"
        ),
        "coquillage-benitier-geant" to CoquillageTranslation(
            nom = "Giant Clam",
            descriptionCourte = "The largest living bivalve in the world, whose massive white shell serves as a carved alternative to ivory.",
            descriptionLongue = "This giant coral-reef mollusc, capable of exceeding one metre in length and several hundred kilograms, produces a massive ivory-white shell with characteristic deep fluting. Protected under the Washington Convention (CITES) due to past overfishing, the species is now farmed under regulation; its shell, sawn and polished, is used in jewellery and sculpture as an alternative to elephant ivory, whose dense, opaque texture it shares.",
            interetJoaillerie = "Good: carved white beads, an ethical alternative to ivory"
        ),
        "coquillage-moule-perliere-eau-douce" to CoquillageTranslation(
            nom = "Freshwater Pearl Mussel",
            descriptionCourte = "A European river mussel whose nacre once fed an entire button-making industry, now vanished.",
            descriptionLongue = "This freshwater mussel, able to live for over a century in the cold, well-oxygenated rivers of Europe and North America, long fed a significant mother-of-pearl button industry along many waterways. Its pinkish-white nacre, finer than that of marine bivalves, is becoming scarce today along with the species itself: river pollution and degradation have made it one of the most endangered molluscs in Europe, now strictly protected.",
            interetJoaillerie = "Historic: freshwater mother-of-pearl button-making, now a protected species"
        ),
        "coquillage-nautile" to CoquillageTranslation(
            nom = "Nautilus",
            descriptionCourte = "A cephalopod with an external shell coiled in a logarithmic spiral, the sole living survivor of a group once dominated by the now-extinct ammonites.",
            descriptionLongue = "The last living representative of an order of external-shelled cephalopods that once counted the ammonites among its relatives, the nautilus lives in the deep waters of Indo-Pacific reefs and rises at night to feed. Sawn crosswise, its shell reveals a series of partitioned chambers arranged in a near-perfect logarithmic spiral, often cited as an example of remarkable natural proportion. The species' fishing is now regulated by CITES due to declining populations.",
            interetJoaillerie = "Very good: framed polished cross-sections, pendants, decorative lighting"
        )
    )
}
